import io
import unittest

from grep import (
    grep,
)
from unittest import mock

FILE_TEXT = {
    "iliad.txt": """Achilles sing, O Goddess! Peleus' son;
His wrath pernicious, who ten thousand woes
Caused to Achaia's host, sent many a soul
Illustrious into Ades premature,
And Heroes gave (so stood the will of Jove)
To dogs and to all ravening fowls a prey,
When fierce dispute had separated once
The noble Chief Achilles from the son
Of Atreus, Agamemnon, King of men.\n""",
    "midsummer-night.txt": """I do entreat your grace to pardon me.
I know not by what power I am made bold,
Nor how it may concern my modesty,
In such a presence here to plead my thoughts;
But I beseech your grace that I may know
The worst that may befall me in this case,
If I refuse to wed Demetrius.\n""",
    "paradise-lost.txt": """Of Mans First Disobedience, and the Fruit
Of that Forbidden Tree, whose mortal tast
Brought Death into the World, and all our woe,
With loss of Eden, till one greater Man
Restore us, and regain the blissful Seat,
Sing Heav'nly Muse, that on the secret top
Of Oreb, or of Sinai, didst inspire
That Shepherd, who first taught the chosen Seed\n""",
}


def open_mock(fname, *args, **kwargs):
    try:
        return io.StringIO(FILE_TEXT[fname])
    except KeyError:
        raise RuntimeError(
            "Expected one of {0!r}: got {1!r}".format(list(FILE_TEXT.keys()), fname)
        )


@mock.patch("grep.open", name="open", side_effect=open_mock, create=True)
@mock.patch("io.StringIO", name="StringIO", wraps=io.StringIO)
class GrepTest(unittest.TestCase):
    # Test grepping a single file
    def test_one_file_one_match_no_flags(self, mock_file, mock_open):
        self.assertMultiLineEqual(
            grep("Agamemnon", "", ["iliad.txt"]), "Of Atreus, Agamemnon, King of men.\n"
        )


if __name__ == "__main__":
    unittest.main()

def _line_body(raw_line):
    if raw_line.endswith("\r\n"):
        return raw_line[:-2]
    if raw_line.endswith("\n"):
        return raw_line[:-1]
    return raw_line


def _matches(body, pattern, ignore_case, whole_line, invert):
    if ignore_case:
        body = body.lower()
        pattern = pattern.lower()

    if whole_line:
        matched = body == pattern
    else:
        matched = pattern in body

    return not matched if invert else matched


def _format_line(filename, line_number, body, multiple_files, with_numbers):
    prefix = []
    if multiple_files:
        prefix.append(filename)
    if with_numbers:
        prefix.append(str(line_number))

    if prefix:
        return ":".join(prefix) + ":" + body + "\n"
    return body + "\n"


def grep(pattern, flags, files):
    active_flags = set(flags.split())
    ignore_case = "-i" in active_flags
    invert = "-v" in active_flags
    whole_line = "-x" in active_flags
    list_files = "-l" in active_flags
    with_numbers = "-n" in active_flags
    multiple_files = len(files) > 1
    result = []

    for filename in files:
        with open(filename) as input_file:
            if list_files:
                for raw_line in input_file:
                    body = _line_body(raw_line)
                    if _matches(body, pattern, ignore_case, whole_line, invert):
                        result.append(filename + "\n")
                        break
                continue

            for line_number, raw_line in enumerate(input_file, start=1):
                body = _line_body(raw_line)
                if _matches(body, pattern, ignore_case, whole_line, invert):
                    result.append(
                        _format_line(
                            filename,
                            line_number,
                            body,
                            multiple_files,
                            with_numbers,
                        )
                    )

    return "".join(result)

